{
  name: 'Все возможные варианты',
  render: args => ({
    components: {
      SocialIcon
    },
    setup() {
      return {
        args,
        variants: meta.argTypes?.icon?.options
      };
    },
    mounted() {
      const style = document.createElement('style');
      style.textContent = `
        .social-icon-instagram {
          background: radial-gradient(
            circle 19.26px at 6.59570325% 96.961876%,
            rgb(255 214 0) 0%,
            rgb(255 105 48 / 100%) 34.4%,
            rgb(254 59 54 / 88%) 58.4%,
            rgb(254 59 54 / 63%) 67%,
            rgb(237 0 192 / 70%) 80%,
            rgb(112 23 255 / 0%) 108%
          ),
          radial-gradient(
            circle at 119.18119812011719% 143.7845001220703%,
            #ff1b90 24.4%,
            #f80261 43.7%,
            #ed00c0 68.8%,
            #c500e9 77.7%,
            #7017ff 89.3%
          );
        }
      `;
      document.head.appendChild(style);
    },
    template: `
      <div class="flex flex-wrap gap-4">
        <div v-for="variant in variants" :key="variant" class="flex flex-col items-center">
          <SocialIcon :class="'social-icon-' + variant" v-bind="{ ...args, icon: variant }" />
          <div class="mt-2">{{ variant }}</div>
        </div>
      </div>
    `
  })
}
